from django.urls import path
from rest_framework.routers import DefaultRouter

from . import views

app_name = "WLMS"

# Every `@action(detail=..., url_path=...)` on these viewsets (wlms/views.py) only resolves
# correctly when the viewset is registered on a DRF router — the sub-routes (e.g.
# `demands/add-to-cart/`, `wediif/add-items/`, `spares/{pk}/routine-context/`) are generated by
# the router from those decorators. Matches the `DefaultRouter` + `router.register(prefix, ...)`
# conversion `obs/urls.py` got earlier (see obs/urls.py). Prefixes below were derived from a full
# grep of every literal `/api/v1/wlms/...` URL `wlms/tests.py` hits.
router = DefaultRouter()
router.register("equipment", views.WLMSEquipmentViewSet)
router.register("spares", views.WLMSSpareViewSet)
router.register("spare-data-maps", views.SpareDataMapViewSet)
router.register("planned-descriptions", views.PlannedSparesDescriptionViewSet)
router.register("planned-spares", views.PlannedWEDSpareListViewSet)
router.register("dart-wed-spares", views.DartWedSpareViewSet)
router.register("survey-receipts", views.SurveyReceiptsDetailsViewSet)
router.register("survey-forms", views.SurveyFormsDetailsViewSet)
router.register("survey-items", views.SurveyFormsItemsViewSet)
router.register("pts-demands", views.PTSDemandDetailsViewSet)
router.register("pts-items", views.PTSItemsViewSet)
router.register("demands", views.DemandDetailsViewSet)
router.register("receive-demands", views.ReceiveDemandDetailsViewSet)
router.register("wediif", views.WEDIIFViewSet)
router.register("wediif-details", views.WEDIIFDetailsViewSet)
router.register("signal-demands", views.SignalDemandViewSet)

urlpatterns = [
    # Standalone `@api_view` functions — not ViewSets, so they stay as manual bindings
    # alongside the router (matching `obs/urls.py`'s pattern for its own non-ViewSet
    # endpoints, e.g. `miscellaneous/`).
    path("send-common-api/", views.send_wed_common_api, name="send-common-api"),
    path("hod-approve/", views.hod_approval, name="hod-approve"),
    path(
        "sync-equipment-from-wed/",
        views.sync_equipment_from_wed,
        name="sync_equipment_from_wed",
    ),
    path(
        "sync-spares-from-wed/",
        views.sync_spares_from_wed,
        name="sync_spares_from_wed",
    ),
    # Also a standalone `@api_view` function (not a ViewSet action): a combined outbox across
    # every workflow type. No router equivalent exists — each viewset's own `/outbox/` action
    # only returns its own record type — so this stays manually bound to avoid silently
    # dropping working functionality during the router conversion.
    path("wlmsoutbox/", views.wlms_combined_outbox, name="wlmsoutbox"),
    # `WLMSSpareViewSet.context_from_query` is a plain method, not `@action`-decorated (it
    # forwards into the `context` detail action using a query param instead of a URL pk), so
    # the router cannot discover it automatically. Kept as a manual binding for the same reason
    # as the entries above.
    path(
        "item-search-detail/",
        views.WLMSSpareViewSet.as_view({"get": "context_from_query"}),
        name="itemsearchwlms_detail",
    ),
] + router.urls
